{
  "implementation": "def solve(case):
    thresh = case.get('threshold')
    calls = case.get('calls')
    if thresh is None or calls is None:
        raise ValueError('Missing threshold or calls')
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        required_keys = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for k in required_keys:
            if k not in call:
                raise ValueError(f'Missing {k} in call')
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        tokens = call['prediction_tokens']
        parseable = call['parseable']
        if tokens <= 0:
            raise ValueError('prediction_tokens must be positive')
        gain = loss_without - loss_with
        normalized_gain = gain / tokens
        normalized_gain = round(normalized_gain, 8)
        accepted = bool(parseable) and normalized_gain >= thresh
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': normalized_gain
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
